  v_pro integer;
BEGIN
  IF public.has_platform_admin(p_user_id) THEN
    RETURN 999999;
  END IF;

  SELECT limits.free_monthly, limits.pro_monthly
  INTO v_free, v_pro
  FROM public.ai_usage_limits AS limits
  WHERE limits.bucket = p_bucket
  LIMIT 1;

  IF v_free IS NULL THEN
