  IF public.is_pro(p_user_id) THEN
    RETURN COALESCE(v_pro, 0);
  END IF;

  IF private.has_free_ai_access_for_user(p_user_id) THEN
    RETURN v_free;
  END IF;

  RETURN 0;
END;

